<?php require_once __DIR__.'/../includes/bootstrap.php'; require_admin(); $cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll(); $edit=null; if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();} $products=db()->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll(); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý sản phẩm</title><link rel="stylesheet" href="../assets/css/style-admin.css"></head><body><div class="admin-container"><aside class="sidebar"><div class="brand">🛡 ADMIN PANEL</div><ul class="menu"><li><a href="index.php">📊 Dashboard</a></li><li class="active"><a href="products.php">📦 Quản lý sản phẩm</a></li><li><a href="categories.php">☷ Danh mục sản phẩm</a></li><li><a href="orders.php">🧾 Quản lý đơn hàng</a></li><li><a href="../index.php">← Về trang chủ</a></li></ul></aside><main class="main-content"><div class="top-header"><h2>Quản lý sản phẩm</h2><button class="btn-add" onclick="openModal()">＋ Thêm sản phẩm</button></div><div class="table-card"><div class="table-header"><h3>Danh sách sản phẩm</h3><span><?=count($products)?> sản phẩm</span></div><table class="admin-table"><thead><tr><th>ID</th><th>Sản phẩm</th><th>Danh mục</th><th>Giá</th><th>Tồn kho</th><th>Hành động</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?=$p['id']?></td><td><strong><?=e($p['name'])?></strong></td><td><?=e($p['category_name'])?></td><td><?=number_format($p['price'],0,',','.')?>đ</td><td><?=$p['stock']?></td><td><a class="btn-action btn-edit" href="?edit=<?=$p['id']?>">Sửa</a><form style="display:inline" method="post" action="../actions/product.php"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn-action btn-delete" onclick="return confirm('Bạn có chắc muốn xóa sản phẩm này không?')">Xóa</button></form></td></tr><?php endforeach; ?></tbody></table></div></main></div><div class="modal-overlay <?= $edit?'is-open':'' ?>" id="productModal"><div class="modal-box"><div class="modal-header"><h3><?= $edit?'Sửa sản phẩm':'Thêm sản phẩm' ?></h3><button class="modal-close" onclick="closeModal()">×</button></div><form class="admin-form" method="post" action="../actions/product.php"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Tên sản phẩm<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Slug<input name="slug" value="<?=e($edit['slug']??'')?>" required></label><label>Danh mục<select name="category_id" required><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?= (($edit['category_id']??0)==$c['id'])?'selected':'' ?>><?=e($c['name'])?></option><?php endforeach; ?></select></label><label>Giá<input type="number" name="price" min="0" value="<?=$edit['price']??0?>" required></label><label>Tồn kho<input type="number" name="stock" min="0" value="<?=$edit['stock']??0?>" required></label><label>URL hình ảnh<input name="image_url" value="<?=e($edit['image_url']??'')?>"></label><label>Mô tả<textarea name="description"><?=e($edit['description']??'')?></textarea></label><div class="form-actions"><button type="button" class="btn-secondary" onclick="closeModal()">Hủy</button><button class="btn-add">Lưu sản phẩm</button></div></form></div></div><script>function openModal(){document.getElementById('productModal').classList.add('is-open')}function closeModal(){document.getElementById('productModal').classList.remove('is-open')}document.getElementById('productModal').addEventListener('click',function(e){if(e.target===this)closeModal()})</script></body></html>
